-- GUIMMIA V76.8 - hard guards, invalidation and read models
create or replace function public.guimmia_v768_sale_case_guard() returns trigger language plpgsql as $$ declare sale_case boolean;begin select exists(select 1 from public.guimmia_case_transaction_profiles p where p.case_id=new.case_id and p.operation_type='SALE' and p.route_status='ROUTED') into sale_case;if not sale_case then raise exception 'v768_sale_case_route_required';end if;return new;end $$;do $$ declare t text;begin foreach t in array array['guimmia_sale_encumbrance_reviews','guimmia_sale_condominium_reviews','guimmia_sale_tax_reviews','guimmia_sale_phase05_snapshots','guimmia_sale_valuation_cases','guimmia_sale_valuation_snapshots','guimmia_sale_listings','guimmia_sale_leads','guimmia_sale_visits','guimmia_sale_negotiation_events','guimmia_sale_offers','guimmia_sale_preliminary_tasks','guimmia_sale_closing_tasks','guimmia_sale_closing_events','guimmia_sale_archive_records','guimmia_sale_operational_tasks'] loop execute format('drop trigger if exists %I on public.%I','trg_'||t||'_sale_case',t);execute format('create trigger %I before insert or update on public.%I for each row execute function public.guimmia_v768_sale_case_guard()','trg_'||t||'_sale_case',t);end loop;end $$;
create or replace function public.guimmia_v768_p05_review_guard() returns trigger language plpgsql as $$ begin if upper(new.status) in('READY','COMPLETED','APPROVED','CLEAR') and (new.review_actor_type is distinct from 'PROFESSIONAL' or new.reviewer_role is null or new.reviewed_by is null or new.reviewed_at is null or new.input_fingerprint is null) then raise exception 'v768_professional_p05_review_required';end if;return new;end $$;do $$ declare t text;begin foreach t in array array['guimmia_sale_encumbrance_reviews','guimmia_sale_condominium_reviews','guimmia_sale_tax_reviews'] loop execute format('drop trigger if exists %I on public.%I','trg_'||t||'_professional_review',t);execute format('create trigger %I before insert or update on public.%I for each row execute function public.guimmia_v768_p05_review_guard()','trg_'||t||'_professional_review',t);end loop;end $$;
create or replace function public.guimmia_v768_valuation_guard() returns trigger language plpgsql as $$ begin if new.status='APPROVED' and (coalesce(new.approval_actor_type,'') not in('HUMAN','PROFESSIONAL') or new.approved_by is null or new.approved_at is null or new.min_value is null or new.max_value is null or new.asking_price is null or new.max_value<new.min_value or new.asking_price<new.min_value or new.asking_price>new.max_value or new.input_fingerprint is null) then raise exception 'v768_human_valuation_approval_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v768_valuation_guard on public.guimmia_sale_valuation_cases;create trigger trg_guimmia_v768_valuation_guard before insert or update on public.guimmia_sale_valuation_cases for each row execute function public.guimmia_v768_valuation_guard();
create or replace function public.guimmia_v768_valuation_snapshot_guard() returns trigger language plpgsql as $$ begin if new.status='APPROVED' and (coalesce(new.approval_actor_type,'') not in('HUMAN','PROFESSIONAL') or new.approved_by is null or new.approved_at is null or new.input_fingerprint is null or new.snapshot='{}'::jsonb) then raise exception 'v768_approved_valuation_snapshot_evidence_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v768_valuation_snapshot_guard on public.guimmia_sale_valuation_snapshots;create trigger trg_guimmia_v768_valuation_snapshot_guard before insert on public.guimmia_sale_valuation_snapshots for each row execute function public.guimmia_v768_valuation_snapshot_guard();
create or replace function public.guimmia_v768_listing_guard() returns trigger language plpgsql as $$ declare gate_ready boolean;valuation_ready boolean;begin if new.status='PUBLISHED' and (tg_op='INSERT' or old.status is distinct from 'PUBLISHED') then if new.approval_actor_type is distinct from 'HUMAN' or new.approved_by is null or new.approved_at is null or new.valuation_snapshot_id is null or new.facts_fingerprint is null then raise exception 'v768_listing_human_approval_required';end if;select exists(select 1 from public.guimmia_sale_valuation_snapshots v where v.id=new.valuation_snapshot_id and v.case_id=new.case_id and v.status='APPROVED' and v.approval_actor_type in('HUMAN','PROFESSIONAL') and v.approved_by is not null and v.approved_at is not null) into valuation_ready;if not valuation_ready then raise exception 'v768_approved_valuation_snapshot_required';end if;select exists(select 1 from public.guimmia_transaction_gate_states g where g.case_id=new.case_id and g.gate_code='PUBLICATION' and g.status='READY') into gate_ready;if not gate_ready then raise exception 'v768_publication_gate_not_ready';end if;end if;return new;end $$;drop trigger if exists trg_guimmia_v768_listing_guard on public.guimmia_sale_listings;create trigger trg_guimmia_v768_listing_guard before insert or update on public.guimmia_sale_listings for each row execute function public.guimmia_v768_listing_guard();
create or replace function public.guimmia_v768_lead_guard() returns trigger language plpgsql as $$ begin if new.status not in('NEW','CLOSED') and new.consent_status<>'GRANTED' then raise exception 'v768_lead_consent_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v768_lead_guard on public.guimmia_sale_leads;create trigger trg_guimmia_v768_lead_guard before insert or update on public.guimmia_sale_leads for each row execute function public.guimmia_v768_lead_guard();
create or replace function public.guimmia_v768_visit_guard() returns trigger language plpgsql as $$ begin if new.status in('CONFIRMED','COMPLETED') and (not new.access_authorized or new.privacy_status<>'READY') then raise exception 'v768_visit_access_privacy_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v768_visit_guard on public.guimmia_sale_visits;create trigger trg_guimmia_v768_visit_guard before insert or update on public.guimmia_sale_visits for each row execute function public.guimmia_v768_visit_guard();
create or replace function public.guimmia_v768_negotiation_guard() returns trigger language plpgsql as $$ begin if new.event_type in('OWNER_DECISION','COUNTEROFFER_APPROVED') and (new.actor_type is distinct from 'HUMAN' or new.actor_id is null) then raise exception 'v768_human_negotiation_decision_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v768_negotiation_guard on public.guimmia_sale_negotiation_events;create trigger trg_guimmia_v768_negotiation_guard before insert on public.guimmia_sale_negotiation_events for each row execute function public.guimmia_v768_negotiation_guard();
create or replace function public.guimmia_v768_offer_guard() returns trigger language plpgsql as $$ declare gate_ready boolean;begin if new.status in('REVIEWED','SUBMITTED') and (new.review_actor_type is distinct from 'HUMAN' or new.reviewed_by is null or new.content_hash is null) then raise exception 'v768_human_offer_review_required';end if;if new.status in('ACCEPTED','REJECTED') and (tg_op='INSERT' or old.status is distinct from new.status) then if new.decision_actor_type is distinct from 'HUMAN' or new.decided_by is null or new.decided_at is null then raise exception 'v768_human_offer_decision_required';end if;select exists(select 1 from public.guimmia_transaction_gate_states g where g.case_id=new.case_id and g.gate_code='OFFER' and g.status='READY') into gate_ready;if not gate_ready then raise exception 'v768_offer_gate_not_ready';end if;end if;return new;end $$;drop trigger if exists trg_guimmia_v768_offer_guard on public.guimmia_sale_offers;create trigger trg_guimmia_v768_offer_guard before insert or update on public.guimmia_sale_offers for each row execute function public.guimmia_v768_offer_guard();
create or replace function public.guimmia_v768_preliminary_guard() returns trigger language plpgsql as $$ begin if new.status='COMPLETED' and (new.reviewed_by is null or coalesce(new.review_actor_type,'') not in('HUMAN','PROFESSIONAL') or new.evidence='[]'::jsonb) then raise exception 'v768_preliminary_review_evidence_required';end if;if new.status='COMPLETED' and new.professional_required and (new.review_actor_type is distinct from 'PROFESSIONAL' or new.reviewer_role is null) then raise exception 'v768_preliminary_professional_review_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v768_preliminary_guard on public.guimmia_sale_preliminary_tasks;create trigger trg_guimmia_v768_preliminary_guard before insert or update on public.guimmia_sale_preliminary_tasks for each row execute function public.guimmia_v768_preliminary_guard();
create or replace function public.guimmia_v768_closing_task_guard() returns trigger language plpgsql as $$ begin if new.status='COMPLETED' and (coalesce(new.completion_actor_type,'') not in('HUMAN','PROFESSIONAL') or new.notary_ref is null or new.completed_by is null or new.completed_at is null or new.evidence='[]'::jsonb) then raise exception 'v768_notary_closing_evidence_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v768_closing_task_guard on public.guimmia_sale_closing_tasks;create trigger trg_guimmia_v768_closing_task_guard before insert or update on public.guimmia_sale_closing_tasks for each row execute function public.guimmia_v768_closing_task_guard();
create or replace function public.guimmia_v768_archive_guard() returns trigger language plpgsql as $$ declare closing_ok boolean;begin if new.status='ARCHIVED' then select exists(select 1 from public.guimmia_sale_closing_events e where e.case_id=new.case_id and e.event_type='COMPLETED' and e.actor_type='HUMAN') into closing_ok;if not closing_ok or new.closure_actor_type is distinct from 'HUMAN' or not new.audit_complete or new.closed_by is null or new.closed_at is null or new.final_documents='[]'::jsonb or new.retention_plan='{}'::jsonb then raise exception 'v768_archive_completeness_required';end if;end if;return new;end $$;drop trigger if exists trg_guimmia_v768_archive_guard on public.guimmia_sale_archive_records;create trigger trg_guimmia_v768_archive_guard before insert or update on public.guimmia_sale_archive_records for each row execute function public.guimmia_v768_archive_guard();
create or replace function public.guimmia_v768_event_immutable() returns trigger language plpgsql as $$ begin raise exception 'V76.8 sale events and approved snapshots are immutable; append a compensating event';end $$;do $$ declare t text;begin foreach t in array array['guimmia_sale_publication_events','guimmia_sale_negotiation_events','guimmia_sale_offer_events','guimmia_sale_closing_events','guimmia_sale_phase05_snapshots','guimmia_sale_valuation_snapshots'] loop execute format('drop trigger if exists %I on public.%I','trg_'||t||'_immutable',t);execute format('create trigger %I before update or delete on public.%I for each row execute function public.guimmia_v768_event_immutable()','trg_'||t||'_immutable',t);end loop;end $$;
create or replace function public.guimmia_v768_invalidate_sale() returns trigger language plpgsql as $$ begin update public.guimmia_sale_listings set status='IN_REVIEW',updated_at=now() where case_id=new.case_id and status in('READY','PUBLISHED','PAUSED');update public.guimmia_sale_offers set status='DRAFT',updated_at=now() where case_id=new.case_id and status in('REVIEWED','SUBMITTED');return new;end $$;drop trigger if exists trg_guimmia_v768_technical_invalidate on public.guimmia_brain_technical_snapshots;create trigger trg_guimmia_v768_technical_invalidate after insert on public.guimmia_brain_technical_snapshots for each row execute function public.guimmia_v768_invalidate_sale();drop trigger if exists trg_guimmia_v768_phase05_invalidate on public.guimmia_sale_phase05_snapshots;create trigger trg_guimmia_v768_phase05_invalidate after insert on public.guimmia_sale_phase05_snapshots for each row execute function public.guimmia_v768_invalidate_sale();
create or replace function public.guimmia_v768_closing_event_guard() returns trigger language plpgsql as $$ declare gate_ready boolean;begin if new.event_type='COMPLETED' then if new.actor_type is distinct from 'HUMAN' or new.actor_id is null then raise exception 'v768_human_closing_completion_required';end if;select exists(select 1 from public.guimmia_transaction_gate_states g where g.case_id=new.case_id and g.gate_code='CLOSING' and g.status='READY') into gate_ready;if not gate_ready then raise exception 'v768_closing_gate_not_ready';end if;end if;return new;end $$;drop trigger if exists trg_guimmia_v768_closing_event_guard on public.guimmia_sale_closing_events;create trigger trg_guimmia_v768_closing_event_guard before insert on public.guimmia_sale_closing_events for each row execute function public.guimmia_v768_closing_event_guard();
create or replace function public.guimmia_v768_offer_event_guard() returns trigger language plpgsql as $$ begin if new.event_type in('ACCEPTED','REJECTED') and (new.actor_type is distinct from 'HUMAN' or new.actor_id is null) then raise exception 'v768_human_offer_event_required';end if;return new;end $$;drop trigger if exists trg_guimmia_v768_offer_event_guard on public.guimmia_sale_offer_events;create trigger trg_guimmia_v768_offer_event_guard before insert on public.guimmia_sale_offer_events for each row execute function public.guimmia_v768_offer_event_guard();
create or replace function public.guimmia_sale_operations_summary(p_case_id uuid) returns table(case_id uuid,listing_status text,lead_count bigint,visit_count bigint,offer_status text,open_task_count bigint,archive_status text) language sql stable security definer set search_path=public as $$ select c.id,coalesce((select l.status from public.guimmia_sale_listings l where l.case_id=c.id order by l.updated_at desc limit 1),'N/A'),(select count(*) from public.guimmia_sale_leads x where x.case_id=c.id),(select count(*) from public.guimmia_sale_visits x where x.case_id=c.id),coalesce((select o.status from public.guimmia_sale_offers o where o.case_id=c.id order by o.updated_at desc limit 1),'N/A'),(select count(*) from public.guimmia_sale_operational_tasks t where t.case_id=c.id and t.status<>'COMPLETED'),coalesce((select a.status from public.guimmia_sale_archive_records a where a.case_id=c.id),'N/A') from public.guimmia_brain_cases c where c.id=p_case_id;$$;revoke all on function public.guimmia_sale_operations_summary(uuid) from public;
create or replace function public.guimmia_sale_action_queue(p_case_id uuid default null) returns table(source_type text,source_id text,case_id uuid,priority text,status text,due_at timestamptz,assigned_to uuid,reason_code text) language sql stable security definer set search_path=public as $$ select 'SALE_TASK',t.id::text,t.case_id,t.priority,t.status,t.due_at,t.assigned_to,t.task_code from public.guimmia_sale_operational_tasks t where t.status<>'COMPLETED' and (p_case_id is null or t.case_id=p_case_id) union all select 'CLOSING_TASK',t.id::text,t.case_id,'HIGH',t.status,t.due_at,null::uuid,t.task_code from public.guimmia_sale_closing_tasks t where t.status<>'COMPLETED' and (p_case_id is null or t.case_id=p_case_id);$$;revoke all on function public.guimmia_sale_action_queue(uuid) from public;
create or replace function public.guimmia_sale_pipeline_metrics(p_case_id uuid default null) returns table(metric text,value bigint) language sql stable security definer set search_path=public as $$ select 'LEADS',count(*) from public.guimmia_sale_leads where p_case_id is null or case_id=p_case_id union all select 'VISITS',count(*) from public.guimmia_sale_visits where p_case_id is null or case_id=p_case_id union all select 'OFFERS',count(*) from public.guimmia_sale_offers where p_case_id is null or case_id=p_case_id;$$;revoke all on function public.guimmia_sale_pipeline_metrics(uuid) from public;
